import test from 'node:test';
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { openDatabase,atomic } from '../src/database.js';
import { Service } from '../src/service.js';
import { Simulation,startScheduler } from '../src/simulation.js';
import { polygon,vertices,fitsPolygon } from '../src/domain/geometry.js';
import { truckStage } from '../public/visual.js';

export function fixture(t){const db=openDatabase(':memory:');t.after(()=>db.close());const auth=new Service(db);const user=auth.authenticate(auth.register({name:'Owner',companyName:'Demo',email:randomUUID()+'@example.com',password:'demonstration-password',systems:['quickstage']}));const sim=new Simulation(db,user);const cmd=(action,input={},key=randomUUID())=>sim.execute(action,input,key);const yard=cmd('yard',{name:'Yard',segments:[{direction:'RIGHT',length:20000},{direction:'DOWN',length:16000},{direction:'LEFT',length:20000}],closed:true});const products=cmd('seed');cmd('resources',{location:yard.id,workers:5,machines:1,stepMs:100,speed:100000,jobs:false});const truck=cmd('truck',{name:'T01',yard:yard.id});const site=cmd('site',{name:'Site A'});cmd('resources',{location:site.id,workers:2,machines:1,stepMs:100,speed:100000,jobs:false});const container=(name,x=4000,y=4000,extra={})=>cmd('container',{name,location:yard.id,type:'STILLAGE',length:2000,width:1000,height:1000,tare:50000,x,y,...extra});const a=container('A'),b=container('B',7000),empty=container('Empty',10000);for(const c of [a,b])cmd('opening',{container:c.id,product:products[0].id,quantity:100,reason:'DEMO ONLY opening'});const tick=(n=30)=>{for(let i=0;i<n;i++)atomic(db,()=>sim.tick(1000));};const total=()=>sim.snapshot().balances.reduce((s,l)=>s+l.quantity,0);return {db,auth,user,sim,cmd,yard,products,truck,site,a,b,empty,container,tick,total};}
test('true diagonal length, self intersection, irregular footprint and explicit close',()=>{const p=vertices([{direction:'SE',length:5000}])[1];assert.ok(Math.abs(Math.hypot(p.x,p.y)-5000)<0.0001);assert.throws(()=>polygon([{direction:'RIGHT',length:1000}],false));assert.throws(()=>polygon([{direction:'SE',length:5000},{direction:'LEFT',length:3500},{direction:'NE',length:5000}],true));const poly=[{x:0,y:0},{x:6000,y:0},{x:6000,y:2000},{x:2000,y:2000},{x:2000,y:6000},{x:0,y:6000}];assert.equal(fitsPolygon({x:1000,y:1000,w:4000,h:4000},poly),false);});
test('reservation, pickup custody, completion, idempotency and total conservation',t=>{const f=fixture(t),key=randomUUID();const task=f.cmd('queue',{container:f.a.id,destination:f.truck.id},key);assert.equal(f.total(),200);assert.equal(f.sim.snapshot().balances.find(l=>l.container===f.a.id).reserved,100);assert.equal(f.cmd('queue',{container:f.a.id,destination:f.truck.id},key).id,task.id);f.tick(9);const current=f.sim.repo.get(task.id);assert.equal(current.state,'CARRYING');assert.equal(f.sim.repo.get(f.a.id).location,current.machine);assert.equal(f.total(),200);assert.throws(()=>f.cmd('cancel',{id:task.id}),/cannot teleport/);f.tick();assert.equal(f.sim.repo.get(f.a.id).location,f.truck.id);assert.equal(f.total(),200);const ledger=f.sim.repo.history(200).filter(l=>l.task_id===task.id);assert.equal(ledger.filter(l=>l.event==='PICKUP').length,1);assert.equal(ledger.filter(l=>l.event==='PLACEMENT').length,1);f.tick();assert.equal(f.sim.repo.history(200).filter(l=>l.task_id===task.id).length,2);});
test('exact full and partial allocation, delivery, partial unload and return loop',t=>{const f=fixture(t);const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:120});f.cmd('allocate',{id:request.id,truck:f.truck.id});f.tick(100);let blocked=f.sim.tasks().filter(t=>t.state==='BLOCKED');for(const task of blocked)f.cmd('retry',{id:task.id});f.tick(100);assert.deepEqual(f.sim.tasks().filter(t=>t.state==='BLOCKED').map(t=>t.reason),[]);assert.equal(f.sim.repo.quantity(f.b.id,f.products[0].id),80);assert.equal(f.sim.repo.quantity(f.empty.id,f.products[0].id),20);assert.equal(f.total(),200);f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});assert.equal(f.sim.snapshot().balances.filter(l=>l.location===f.site.id).length,0);f.tick(5);assert.equal(f.sim.snapshot().balances.filter(l=>l.location===f.site.id).length,0);f.cmd('queue',{container:f.a.id,destination:f.site.id});f.tick();assert.equal(f.sim.snapshot().balances.filter(l=>l.location===f.site.id).reduce((s,l)=>s+l.quantity,0),100);assert.equal(f.sim.repo.get(f.empty.id).location,f.truck.id);f.cmd('unload',{id:f.truck.id});f.tick();assert.equal(f.sim.repo.get(request.id).status,'DELIVERED');f.cmd('returnStock',{container:f.a.id,truck:f.truck.id});f.tick();f.cmd('returnStock',{container:f.empty.id,truck:f.truck.id});f.tick();f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});f.tick(5);f.cmd('unload',{id:f.truck.id});f.tick(60);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(60);assert.equal(f.total(),200);assert.equal(f.sim.snapshot().balances.filter(l=>l.location===f.yard.id).reduce((s,l)=>s+l.quantity,0),200);});
test('payload includes tare once; at capacity succeeds; queued overbooking fails atomically',t=>{const f=fixture(t);const truck=f.sim.repo.get(f.truck.id);truck.payload=550000;f.sim.repo.save(truck);f.cmd('queue',{container:f.a.id,destination:truck.id});assert.equal(f.sim.snapshot().trucks[0].reservedWeight,550000);assert.throws(()=>f.cmd('queue',{container:f.b.id,destination:truck.id}),/payload|footprint/);assert.equal(f.sim.tasks().length,1);f.tick();assert.equal(f.sim.snapshot().trucks[0].loadedWeight,550000);});
test('overlap, oversize, unsupported stacks, lower container and height rules',t=>{const f=fixture(t);assert.throws(()=>f.container('Overlap',4000,4000),/overlap/);assert.throws(()=>f.container('Unsupported',12000,4000,{support:'missing'}),/support/);const upper=f.container('Upper',4000,4000,{support:f.a.id});assert.throws(()=>f.cmd('queue',{container:f.a.id,destination:f.truck.id}),/top stillage/);assert.throws(()=>f.cmd('queue',{container:upper.id,destination:f.truck.id,position:{x:5500,y:0,rotation:0}}),/envelope/);let support=upper;for(let i=3;i<=7;i++)support=f.container('Stack '+i,4000,4000,{support:support.id});assert.throws(()=>f.container('Eighth',4000,4000,{support:support.id}),/Maximum 7/);});
test('no equipment blocks; busy equipment queues fairly without double booking',t=>{const f=fixture(t);f.cmd('resources',{location:f.yard.id,workers:0,machines:0});const task=f.cmd('queue',{container:f.a.id,destination:f.truck.id});f.tick();assert.equal(f.sim.repo.get(task.id).state,'BLOCKED');assert.match(f.sim.repo.get(task.id).reason,/forklift/);f.cmd('resources',{location:f.yard.id,workers:5,machines:1});f.cmd('retry',{id:task.id});const second=f.cmd('queue',{container:f.b.id,destination:f.truck.id});f.tick(3);const resources=f.sim.repo.all('resource').filter(r=>r.task);assert.equal(new Set(resources.map(r=>r.id)).size,resources.length);assert.equal(resources.length,2);assert.equal(f.sim.repo.get(second.id).state,'RESERVED');assert.throws(()=>f.cmd('resources',{location:f.yard.id,workers:0,machines:0}),/busy/);f.tick(80);assert.equal(f.sim.repo.get(second.id).state,'COMPLETE');});
test('cancel before pickup releases stock and destination reservations',t=>{const f=fixture(t);const task=f.cmd('queue',{container:f.a.id,destination:f.truck.id});f.cmd('cancel',{id:task.id});assert.equal(f.sim.snapshot().balances.find(l=>l.container===f.a.id).reserved,0);assert.equal(f.sim.snapshot().trucks[0].reservedWeight,0);assert.equal(f.sim.repo.get(f.a.id).location,f.yard.id);});
test('unknown weight and pack settings block only affected operation; provenance conflicts fail',t=>{const f=fixture(t);f.cmd('opening',{container:f.empty.id,product:f.products[2].id,quantity:5,reason:'Demo unknown'});assert.throws(()=>f.cmd('queue',{container:f.empty.id,destination:f.truck.id}),/unknown/);const r=f.cmd('request',{site:f.site.id,product:f.products[2].id,quantity:1});assert.throws(()=>f.cmd('allocate',{id:r.id,truck:f.truck.id}),/Full-pack/);assert.throws(()=>f.cmd('product',{name:'Duplicate',reference:'DEMO-L2000',system:'quickstage',verification:'DEMO ONLY'}),/conflicting/);f.auth.updateCompany(f.user,{name:'Demo',systems:['at-pac']});assert.equal(f.total(),205);assert.equal(f.sim.snapshot().products.length,3);});
test('stocktake locks scope, requires reason and permission, records variance',t=>{const f=fixture(t);const count=f.cmd('count',{scope:f.a.id});assert.throws(()=>f.cmd('queue',{container:f.a.id,destination:f.truck.id}),/stocktake/);assert.throws(()=>f.cmd('observe',{id:count.id,observed:[95],reason:''}),/reason/);f.cmd('observe',{id:count.id,observed:[95],reason:'Five missing in demonstration count'});f.cmd('approveCount',{id:count.id});assert.equal(f.total(),195);assert.equal(f.sim.repo.history(200).filter(l=>l.event==='STOCKTAKE_ADJUSTMENT')[0].quantity,-5);assert.throws(()=>f.db.prepare('DELETE FROM ledger').run(),/append only/);});
test('tenant guessed IDs, supervisor site scope and adjustment permission',t=>{const f=fixture(t);f.auth.addUser(f.user,{name:'Supervisor',email:'supervisor@example.com',password:'demonstration-password',roles:['SUPERVISOR']});const supervisor=f.auth.authenticate(f.auth.login({email:'supervisor@example.com',password:'demonstration-password'}));const restricted=new Simulation(f.db,supervisor);assert.equal(restricted.snapshot().sites.length,0);assert.throws(()=>restricted.execute('request',{site:f.site.id,product:f.products[0].id,quantity:1},randomUUID()),/assigned/);assert.throws(()=>restricted.execute('approveCount',{id:'guessed'},randomUUID()),{status:403});const other=f.auth.authenticate(f.auth.register({name:'Other',companyName:'Other',email:'other@example.com',password:'demonstration-password',systems:['quickstage']}));const isolated=new Simulation(f.db,other);assert.throws(()=>isolated.execute('queue',{container:f.a.id,destination:f.truck.id},randomUUID()),{status:404});assert.equal(isolated.snapshot().balances.length,0);assert.ok(!isolated.export('stock').includes('DEMO ledger'));});
test('archival retains history and refuses occupied sites; engine singleton guard',t=>{const f=fixture(t);f.cmd('archive',{id:f.site.id});assert.equal(f.sim.repo.get(f.site.id).status,'ARCHIVED');assert.ok(f.sim.repo.history(200).some(l=>l.event==='SITE_ARCHIVED'));const stop=startScheduler(f.db);assert.throws(()=>startScheduler(f.db),/Another movement engine/);stop();});
test('placement input cannot overwrite identity, custody, tare or content',t=>{const f=fixture(t);f.cmd('queue',{container:f.a.id,destination:f.truck.id,position:{x:0,y:0,rotation:0,id:'forged',location:f.site.id,tare:0}});f.tick();const c=f.sim.repo.get(f.a.id);assert.equal(c.id,f.a.id);assert.equal(c.location,f.truck.id);assert.equal(c.tare,50000);assert.equal(f.total(),200);});
test('active destination count prevents incoming movement reservations',t=>{const f=fixture(t);f.cmd('queue',{container:f.a.id,destination:f.truck.id});f.tick();f.cmd('count',{scope:f.yard.id});assert.throws(()=>f.cmd('queue',{container:f.a.id,destination:f.yard.id}),/stocktake/);assert.equal(f.sim.repo.get(f.a.id).location,f.truck.id);assert.equal(f.total(),200);});
test('cancelling a request releases its exact unstarted reservations and deck claims',t=>{const f=fixture(t);const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:120});f.cmd('allocate',{id:request.id,truck:f.truck.id});f.cmd('cancelRequest',{id:request.id,reason:'Demonstration request cancelled'});assert.equal(f.sim.snapshot().reservedTotal,0);assert.equal(f.sim.snapshot().trucks[0].reservedWeight,0);assert.equal(f.sim.tasks().filter(t=>t.state!=='CANCELLED').length,0);assert.equal(f.total(),200);assert.equal(f.sim.repo.get(f.truck.id).destination,null,'cancelling the only booking clears the destination');});
test('reviewed catalogue batch conflicts roll back all new variants and provenance',t=>{const f=fixture(t);const before=f.sim.repo.all('source').length;assert.throws(()=>f.cmd('importCatalogue',{name:'Reviewed test batch',products:[{name:'New demo',reference:'NEW-DEMO',system:'quickstage',verification:'DEMO ONLY'},{name:'Conflicting',reference:'DEMO-L2000',system:'quickstage',verification:'DEMO ONLY'}]}),/conflicting/);assert.equal(f.sim.repo.all('product').length,3);assert.equal(f.sim.repo.all('source').length,before);assert.equal(f.sim.repo.all('importBatch').length,0);});

test('parking dimensions persist independently of storage and reject invalid sizes',t=>{const f=fixture(t);const saved=f.cmd('parking',{id:f.yard.id,side:'RIGHT',vehicleLength:9000,vehicleWidth:2100,clearance:500});assert.equal(saved.parking.length,10000);assert.equal(saved.parking.width,3100);assert.equal(saved.area,f.yard.area);assert.equal(f.sim.snapshot().yards[0].parking.width,3100);assert.throws(()=>f.cmd('parking',{id:f.yard.id,side:'RIGHT',vehicleLength:-1,vehicleWidth:2100,clearance:500}));assert.equal(f.sim.snapshot().yards[0].parking.length,10000);assert.equal(f.total(),200);});
test('home availability excludes damaged stock and counts cages across storage',t=>{const f=fixture(t);f.container('Fittings cage',13000,4000,{type:'CAGE',length:1200});f.cmd('condition',{id:f.a.id,condition:'DAMAGED',reason:'Inspection'});const summary=f.sim.snapshot().availability;assert.equal(summary.cages,1);assert.equal(summary.stillages,3);assert.equal(summary.serviceablePieces,100);});

test('worker orders persist, avoid obstacles, hold, stop and resume automatic availability',t=>{const f=fixture(t),w=f.sim.snapshot().resources.find(r=>r.type==='WORKER'&&r.location===f.yard.id);assert.ok(Number.isFinite(w.x));const moved=f.cmd('workerCommand',{id:w.id,order:'MOVE',x:15000,y:12000});assert.equal(moved.workerMode,'MOVING');f.tick(2);const walking=f.sim.repo.get(w.id);assert.notEqual(walking.x,w.x);assert.ok(walking.walk);f.cmd('workerCommand',{id:w.id,order:'STOP'});const stopped=f.sim.repo.get(w.id);f.tick(2);assert.equal(f.sim.repo.get(w.id).x,stopped.x);assert.equal(stopped.walk,null);assert.equal(stopped.workerMode,'HOLD');assert.throws(()=>f.cmd('workerCommand',{id:w.id,order:'MOVE',x:4000,y:4000}),/route/);assert.throws(()=>f.cmd('workerCommand',{id:w.id,order:'MOVE',x:-1000,y:-1000}),/route/);f.cmd('workerCommand',{id:w.id,order:'MOVE',x:15000,y:12000});f.tick(30);assert.equal(f.sim.repo.get(w.id).x,15000);assert.equal(f.sim.repo.get(w.id).y,12000);f.cmd('workerCommand',{id:w.id,order:'AUTO'});assert.equal(f.sim.repo.get(w.id).workerMode,'AUTO');});
test('manual workers cannot be claimed by automatic tasks and busy workers reject orders',t=>{const f=fixture(t),workers=f.sim.snapshot().resources.filter(r=>r.type==='WORKER'&&r.location===f.yard.id);for(const w of workers)f.cmd('workerCommand',{id:w.id,order:'HOLD'});const task=f.cmd('queue',{container:f.a.id,destination:f.truck.id});f.tick(3);assert.equal(f.sim.repo.get(task.id).state,'BLOCKED');f.cmd('workerCommand',{id:workers[0].id,order:'AUTO'});f.cmd('retry',{id:task.id});f.tick(2);assert.ok(f.sim.repo.get(workers[0].id).task);assert.throws(()=>f.cmd('workerCommand',{id:workers[0].id,order:'MOVE',x:1000,y:1000}),/assigned/);});

test('paused simulation freezes walking and resumes from saved position',t=>{const f=fixture(t),w=f.sim.snapshot().resources.find(r=>r.type==='WORKER');f.cmd('workerCommand',{id:w.id,order:'MOVE',x:15000,y:12000});f.tick(2);const before=f.sim.repo.get(w.id);f.cmd('pause',{paused:true});f.tick(10);assert.equal(f.sim.repo.get(w.id).x,before.x);assert.deepEqual(f.sim.repo.get(w.id).walk,before.walk);f.cmd('pause',{paused:false});f.tick(30);assert.equal(f.sim.repo.get(w.id).x,15000);assert.equal(f.sim.repo.get(w.id).workerMode,'HOLD');});

test('mount reserves forklift, walks before attaching, survives reload and dismounts',t=>{const f=fixture(t),snapshot=f.sim.snapshot(),workers=snapshot.resources.filter(r=>r.type==='WORKER'&&r.location===f.yard.id),machine=snapshot.resources.find(r=>r.type==='FORKLIFT');const walking=f.cmd('workerCommand',{id:workers[0].id,order:'MOUNT',forklift:machine.id});assert.ok(walking.walk);assert.equal(walking.mountedOn,undefined);assert.equal(f.sim.repo.get(machine.id).claimedBy,workers[0].id);assert.throws(()=>f.cmd('workerCommand',{id:workers[1].id,order:'MOUNT',forklift:machine.id}),/reserved/);f.tick(50);assert.equal(f.sim.repo.get(workers[0].id).mountedOn,machine.id);assert.equal(f.sim.repo.get(machine.id).driver,workers[0].id);assert.equal(new Simulation(f.db,f.user).snapshot().resources.find(r=>r.id===machine.id).driver,workers[0].id);f.cmd('workerCommand',{id:workers[0].id,order:'MOVE',x:9000,y:9000});assert.ok(f.sim.repo.get(machine.id).drive);f.cmd('workerCommand',{id:workers[0].id,order:'STOP'});assert.throws(()=>f.cmd('resources',{location:f.yard.id,workers:0,machines:0}),/busy/);f.cmd('workerCommand',{id:workers[0].id,order:'DISMOUNT'});assert.equal(f.sim.repo.get(machine.id).driver,null);assert.equal(f.sim.repo.get(workers[0].id).mountedOn,null);assert.equal(f.sim.repo.get(workers[0].id).workerMode,'HOLD');});
test('cancel mounting releases claim and cross-location mount fails',t=>{const f=fixture(t),resources=f.sim.snapshot().resources,w=resources.find(r=>r.type==='WORKER'&&r.location===f.yard.id),m=resources.find(r=>r.type==='FORKLIFT'),crane=resources.find(r=>r.type==='CRANE');assert.throws(()=>f.cmd('workerCommand',{id:w.id,order:'MOUNT',forklift:crane.id}),/forklift/);f.cmd('workerCommand',{id:w.id,order:'MOUNT',forklift:m.id});f.cmd('workerCommand',{id:w.id,order:'STOP'});assert.equal(f.sim.repo.get(m.id).claimedBy,null);assert.equal(f.sim.repo.get(w.id).mountTarget,null);f.tick(50);assert.ok(!f.sim.repo.get(m.id).driver);});

function mountedFixture(t){const f=fixture(t),resources=f.sim.snapshot().resources,w=resources.find(r=>r.type==='WORKER'&&r.location===f.yard.id),m=resources.find(r=>r.type==='FORKLIFT');f.cmd('workerCommand',{id:w.id,order:'MOUNT',forklift:m.id});f.tick(40);return {...f,w,m,order:(order,extra={})=>f.cmd('workerCommand',{id:w.id,order,...extra})};}
test('mounted driving and pickup/carry/place preserve exact stock and emit one ledger pair',t=>{const f=mountedFixture(t);f.order('MOVE',{x:13000,y:9000});f.tick(30);assert.equal(f.sim.repo.get(f.m.id).x,13000);assert.equal(f.sim.repo.get(f.w.id).x,13600);f.order('PICKUP',{container:f.a.id});assert.throws(()=>f.cmd('queue',{container:f.a.id,destination:f.truck.id}),/manual forklift/);f.tick(40);let m=f.sim.repo.get(f.m.id);assert.equal(m.cargo,f.a.id,m.manualReason);assert.equal(f.sim.repo.get(f.a.id).location,m.id);assert.equal(f.total(),200);assert.throws(()=>f.order('DISMOUNT'),/place the load/);assert.throws(()=>f.cmd('count',{scope:f.yard.id}),/manual forklift/);assert.throws(()=>f.cmd('opening',{container:f.a.id,product:f.products[0].id,quantity:1,reason:'Do not mutate cargo'}),/manual forklift/);f.order('MOVE',{x:13000,y:9000});f.tick(40);assert.equal(f.sim.repo.get(f.a.id).location,m.id);f.order('PLACE',{x:12000,y:11000});f.tick(40);const c=f.sim.repo.get(f.a.id);assert.equal(c.location,f.yard.id);assert.equal(c.x,12000);assert.equal(c.y,11000);assert.equal(f.sim.repo.get(f.m.id).cargo,null);assert.equal(f.total(),200);const logs=f.sim.repo.history(200).filter(l=>l.container_id===c.id&&['PICKUP','PLACEMENT'].includes(l.event));assert.equal(logs.length,2);f.tick(30);assert.equal(f.sim.repo.history(200).filter(l=>l.container_id===c.id&&['PICKUP','PLACEMENT'].includes(l.event)).length,2);});
test('manual forklift rejects overload and invalid routes and stopping releases pickup claim',t=>{const f=mountedFixture(t),m=f.sim.repo.get(f.m.id);m.capacity=100000;f.sim.repo.save(m);assert.throws(()=>f.order('PICKUP',{container:f.a.id}),/capacity/);m.capacity=1500000;f.sim.repo.save(m);assert.throws(()=>f.order('MOVE',{x:-1000,y:9000}),/route/);f.order('PICKUP',{container:f.a.id});f.order('STOP');assert.equal(f.sim.repo.get(f.m.id).drive,null);f.tick(20);assert.equal(f.sim.repo.get(f.a.id).location,f.yard.id);f.order('PICKUP',{container:f.a.id});f.tick(40);assert.equal(f.sim.repo.get(f.m.id).cargo,f.a.id);assert.throws(()=>f.order('MOVE',{x:18000,y:8000}),/route/);assert.throws(()=>f.order('PLACE',{x:7000,y:4000}),/overlap/);assert.equal(f.sim.repo.get(f.a.id).location,f.m.id);f.order('MOVE',{x:12000,y:10000});f.tick(2);f.cmd('pause',{paused:true});const before=f.sim.repo.get(f.m.id);f.tick(10);assert.equal(f.sim.repo.get(f.m.id).x,before.x);assert.equal(new Simulation(f.db,f.user).repo.get(f.m.id).cargo,f.a.id);});

test('new obstruction stops manual placement without losing carried stock',t=>{const f=mountedFixture(t);f.order('PICKUP',{container:f.a.id});f.tick(40);f.order('PLACE',{x:14000,y:11000});f.container('New obstruction',14000,11000);f.tick(40);const m=f.sim.repo.get(f.m.id);assert.equal(m.cargo,f.a.id);assert.equal(m.drive,null);assert.match(m.manualReason,/blocked/);assert.equal(f.sim.repo.get(f.a.id).location,m.id);assert.equal(f.total(),200);assert.equal(f.sim.repo.history(200).filter(l=>l.event==='PLACEMENT').length,0);});

test('delivery allocation skips stillages claimed by a manual pickup',t=>{const f=mountedFixture(t);f.order('PICKUP',{container:f.a.id});const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:100});const allocated=f.cmd('allocate',{id:request.id,truck:f.truck.id});assert.ok(allocated.tasks.every(task=>task.container!==f.a.id&&task.sourceContainer!==f.a.id));assert.ok(allocated.tasks.some(task=>task.container===f.b.id));});

test('precise preview is read-only and confirmed rotation preserves millimetre coordinates',t=>{const f=mountedFixture(t);f.order('PICKUP',{container:f.a.id});f.tick(40);const before=f.sim.repo.get(f.m.id),logCount=f.sim.repo.history(200).length;const plan=f.sim.placementPreview({id:f.w.id,container:f.a.id,x:12013,y:10027,rotation:90});assert.deepEqual(plan.footprint,{x:12013,y:10027,w:1000,h:2000});assert.ok(plan.rotationClearance);assert.equal(f.sim.repo.get(f.m.id).version,before.version);assert.equal(f.sim.repo.history(200).length,logCount);assert.equal(f.sim.repo.get(f.a.id).rotation,0);f.order('PLACE',{container:f.a.id,x:12013,y:10027,rotation:90});f.tick(40);const c=f.sim.repo.get(f.a.id);assert.equal(c.x,12013);assert.equal(c.y,10027);assert.equal(c.rotation,90);assert.equal(c.location,f.yard.id);assert.equal(f.total(),200);});
test('rotation rejects invalid angles, insufficient clearance, stale load and new obstacles',t=>{const f=mountedFixture(t);f.order('PICKUP',{container:f.a.id});f.tick(40);assert.throws(()=>f.sim.placementPreview({id:f.w.id,x:12000,y:10000,rotation:45}),/0 or 90/);assert.throws(()=>f.order('PLACE',{container:f.b.id,x:12000,y:10000,rotation:90}),/changed/);assert.throws(()=>f.sim.placementPreview({id:f.w.id,x:18000,y:14000,rotation:90}),/rotate|route/);f.sim.placementPreview({id:f.w.id,x:14000,y:10000,rotation:90});f.container('New neighbour',15010,10500,{length:200,width:200});assert.throws(()=>f.order('PLACE',{x:14000,y:10000,rotation:90}),/rotate|route/);assert.equal(f.sim.repo.get(f.a.id).rotation,0);assert.equal(f.sim.repo.get(f.a.id).location,f.m.id);});

test('new obstruction in rotation clearance blocks arrival without rotating or losing cargo',t=>{const f=mountedFixture(t);f.order('PICKUP',{container:f.a.id});f.tick(40);f.order('PLACE',{x:14000,y:10000,rotation:90});f.container('Rotation obstruction',15500,12050,{length:200,width:200});f.tick(40);assert.equal(f.sim.repo.get(f.a.id).location,f.m.id);assert.equal(f.sim.repo.get(f.a.id).rotation,0);assert.match(f.sim.repo.get(f.m.id).manualReason,/rotation/);assert.equal(f.total(),200);});

test('yard loading zone and gate are editable, preserved on later edits, kept inside and clear of stock',t=>{const f=fixture(t),segments=[{direction:'RIGHT',length:20000},{direction:'DOWN',length:16000},{direction:'LEFT',length:20000}];const moved=f.cmd('yard',{id:f.yard.id,name:'Yard',segments,closed:true,loading:{x:15000,y:12000},gate:{x:1000,y:12000}});assert.deepEqual(moved.loading,{x:15000,y:12000});assert.deepEqual(moved.gate,{x:1000,y:12000});const renamed=f.cmd('yard',{id:f.yard.id,name:'Renamed yard',segments,closed:true});assert.equal(renamed.name,'Renamed yard');assert.deepEqual(renamed.loading,{x:15000,y:12000});assert.deepEqual(renamed.gate,{x:1000,y:12000});assert.deepEqual(f.sim.snapshot().yards[0].loading,{x:15000,y:12000});const onto=f.cmd('yard',{id:f.yard.id,name:'Yard',segments,closed:true,loading:{x:3500,y:3500}});assert.deepEqual(onto.relocated,['A']);assert.ok(!(f.sim.repo.get(f.a.id).x<5500&&f.sim.repo.get(f.a.id).y<5000&&f.sim.repo.get(f.a.id).x+2000>3500&&f.sim.repo.get(f.a.id).y+1000>3500),'A moved off the loading zone');const outside=f.cmd('yard',{id:f.yard.id,name:'Yard',segments,closed:true,loading:{x:19000,y:1000}});assert.match(outside.message,/Loading zone moved/);assert.ok(fitsPolygon({...f.sim.repo.get(f.yard.id).loading,w:2000,h:1500},f.sim.repo.get(f.yard.id).points));f.cmd('yard',{id:f.yard.id,name:'Yard',segments,closed:true,loading:{x:15000,y:12000}});assert.deepEqual(f.sim.repo.get(f.yard.id).loading,{x:15000,y:12000});f.cmd('queue',{container:f.a.id,destination:f.truck.id});f.tick(150);assert.equal(f.sim.repo.get(f.a.id).location,f.truck.id);assert.equal(f.total(),200);});

test('materials register totals by location, purchases and removals log with airtight guards',t=>{const f=fixture(t);const reg=()=>f.sim.snapshot().register.find(r=>r.product===f.products[0].id);assert.equal(reg().quantity,200);assert.equal(reg().yard,200);assert.equal(reg().available,200);f.cmd('purchase',{container:f.empty.id,product:f.products[0].id,quantity:40,reason:'Bought stock',supplier:'Demo supplier'});assert.equal(f.total(),240);assert.equal(reg().quantity,240);const additions=f.sim.snapshot().additions;assert.equal(additions[0].event,'PURCHASE');assert.equal(additions[0].quantity,40);assert.match(additions[0].reason,/Demo supplier/);assert.ok(additions.some(l=>l.event==='OPENING_BALANCE'));assert.throws(()=>f.cmd('removeStock',{container:f.empty.id,product:f.products[0].id,quantity:41,reason:'Too many'}),/40 unreserved/);f.cmd('removeStock',{container:f.empty.id,product:f.products[0].id,quantity:15,reason:'Sold to customer'});assert.equal(f.total(),225);assert.equal(reg().quantity,225);const removals=f.sim.snapshot().removals;assert.equal(removals.length,1);assert.equal(removals[0].event,'STOCK_REMOVED');assert.equal(removals[0].quantity,15);f.cmd('queue',{container:f.a.id,destination:f.truck.id});assert.throws(()=>f.cmd('removeStock',{container:f.a.id,product:f.products[0].id,quantity:1,reason:'Reserved'}),/active movement|unreserved/);f.tick(120);assert.equal(f.sim.repo.get(f.a.id).location,f.truck.id);assert.throws(()=>f.cmd('removeStock',{container:f.a.id,product:f.products[0].id,quantity:1,reason:'On truck'}),/truck/);assert.equal(reg().truck,100);f.cmd('count',{scope:f.b.id});assert.throws(()=>f.cmd('removeStock',{container:f.b.id,product:f.products[0].id,quantity:1,reason:'Counting'}),/stocktake/);assert.throws(()=>f.cmd('removeStock',{container:f.empty.id,product:f.products[1].id,quantity:1,reason:'Wrong product'}),/does not hold/);assert.equal(f.total(),225);assert.equal(f.sim.export('register').split('\r\n').length,2);assert.equal(f.sim.export('removals').split('\r\n').length,2);});

test('yard list reserves line by line, reports short lines, loads, travels as the site manifest and completes',t=>{const f=fixture(t);const list=f.cmd('createLoadList',{name:'Monday load',site:f.site.id,lines:[{product:f.products[0].id,quantity:120},{product:f.products[1].id,quantity:10}]});assert.equal(list.lines.length,2);assert.ok(f.sim.repo.all('request').every(r=>r.loadList===list.id));assert.throws(()=>f.cmd('createLoadList',{site:f.site.id,lines:[{product:f.products[0].id,quantity:1},{product:f.products[0].id,quantity:1}]}),/once per yard list/);const before=f.sim.snapshot().loadLists[0];assert.equal(before.status,'OPEN');const result=f.cmd('allocateLoadList',{id:list.id,truck:f.truck.id});assert.equal(result.outcome.find(o=>o.product===f.products[0].id).status,'ALLOCATED');assert.equal(result.outcome.find(o=>o.product===f.products[1].id).status,'SHORT');const partial=f.sim.snapshot().loadLists[0];assert.equal(partial.status,'PARTIAL');assert.equal(partial.short,1);assert.match(partial.lines[1].lastReason,/INSUFFICIENT/);assert.equal(f.sim.snapshot().reservedTotal,120);assert.equal(f.total(),200);f.tick(200);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(200);const loaded=f.sim.snapshot().loadLists[0];assert.equal(loaded.lines[0].loaded,120);assert.equal(f.sim.snapshot().deliveries.length,0);f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});const transit=f.sim.snapshot();assert.equal(transit.loadLists[0].status,'IN_TRANSIT');assert.equal(transit.deliveries[0].manifest.length,1);assert.equal(transit.deliveries[0].manifest[0].name,'Monday load');assert.equal(transit.deliveries[0].manifest[0].lines[0].quantity,120);f.tick(20);f.cmd('unload',{id:f.truck.id});f.tick(300);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(300);const done=f.sim.snapshot().loadLists[0];assert.equal(done.lines[0].status,'DELIVERED');assert.equal(done.lines[0].delivered,120);assert.equal(done.lines[1].status,'REQUESTED');assert.equal(f.total(),200);assert.equal(f.sim.export('yardlist').split('\r\n').length,3);f.cmd('cancelLoadList',{id:list.id,reason:'Remainder not needed'});assert.equal(f.sim.snapshot().loadLists[0].lines[1].status,'CANCELLED');assert.equal(f.sim.snapshot().loadLists[0].status,'CANCELLED');assert.equal(f.total(),200);});

test('yard list allocation is all-or-nothing per line and a fully short list is rejected without side effects',t=>{const f=fixture(t);const list=f.cmd('createLoadList',{site:f.site.id,lines:[{product:f.products[1].id,quantity:5}]});assert.throws(()=>f.cmd('allocateLoadList',{id:list.id,truck:f.truck.id}),/INSUFFICIENT/);assert.equal(f.sim.snapshot().reservedTotal,0);assert.equal(f.sim.tasks().length,0);assert.equal(f.sim.repo.get(list.id).truck,null);assert.equal(f.sim.snapshot().loadLists[0].status,'OPEN');});

test('a truck can be re-planned after a round trip; foreign cargo blocks a new trip',t=>{const f=fixture(t);const first=f.cmd('createLoadList',{name:'Trip 1',site:f.site.id,lines:[{product:f.products[0].id,quantity:100}]});f.cmd('allocateLoadList',{id:first.id,truck:f.truck.id});f.tick(150);f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(20);f.cmd('unload',{id:f.truck.id});f.tick(300);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(300);assert.equal(f.sim.snapshot().loadLists[0].status,'DELIVERED');f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});f.tick(20);assert.equal(f.sim.repo.get(f.truck.id).status,'AT_YARD');assert.equal(f.sim.repo.get(f.truck.id).destination,null);const second=f.cmd('createLoadList',{name:'Trip 2',site:f.site.id,lines:[{product:f.products[0].id,quantity:100}]});const planned=f.cmd('allocateLoadList',{id:second.id,truck:f.truck.id});assert.equal(planned.outcome[0].status,'ALLOCATED');f.tick(150);assert.equal(f.sim.snapshot().loadLists[1].loaded,100);const other=f.cmd('site',{name:'Other site',address:'Elsewhere'});const third=f.cmd('createLoadList',{name:'Trip 3',site:other.id,lines:[{product:f.products[0].id,quantity:1}]});assert.throws(()=>f.cmd('allocateLoadList',{id:third.id,truck:f.truck.id}),/One destination per truck trip/);f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(20);f.cmd('unload',{id:f.truck.id});f.tick(300);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(300);assert.equal(f.sim.snapshot().loadLists[1].status,'DELIVERED');const returning=f.sim.containers().find(c=>c.location===f.site.id);f.cmd('returnStock',{container:returning.id,truck:f.truck.id});f.tick(300);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(300);assert.equal(f.sim.repo.get(returning.id).location,f.truck.id);f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});f.tick(20);assert.equal(f.sim.repo.get(f.truck.id).status,'AT_YARD');assert.throws(()=>f.cmd('allocateLoadList',{id:third.id,truck:f.truck.id}),/Unload the truck/);f.cmd('unload',{id:f.truck.id});f.tick(300);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(300);assert.equal(f.cmd('allocateLoadList',{id:third.id,truck:f.truck.id}).outcome[0].status,'ALLOCATED');assert.equal(f.total(),200);});

test('yard list cannot be re-pointed to another truck, its lines cannot be cancelled outside the list, and a cancelled loading task blocks departure',t=>{const f=fixture(t);const t2=f.cmd('truck',{name:'T02',yard:f.yard.id});const list=f.cmd('createLoadList',{name:'Guarded',site:f.site.id,lines:[{product:f.products[0].id,quantity:120}]});f.cmd('allocateLoadList',{id:list.id,truck:f.truck.id});assert.throws(()=>f.cmd('allocateLoadList',{id:list.id,truck:t2.id}),/another truck/);assert.throws(()=>f.cmd('allocateLoadList',{id:list.id,truck:f.truck.id}),/already planned/);assert.equal(f.sim.repo.get(list.id).truck,f.truck.id);assert.throws(()=>f.cmd('cancelRequest',{id:list.lines[0].request,reason:'Side door'}),/Cancel the yard list/);f.tick(150);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(150);const pending=f.sim.tasks().filter(t=>['QUEUED','RESERVED'].includes(t.state)&&!t.picked);const loadedOnTruck=f.sim.snapshot().loadLists[0].loaded;if(pending.length){for(const task of pending.filter(t=>!f.sim.tasks().some(o=>o.dependency===t.id)))f.cmd('cancel',{id:task.id});for(const task of f.sim.tasks().filter(t=>['QUEUED','RESERVED'].includes(t.state)&&!t.picked))f.cmd('cancel',{id:task.id});assert.equal(f.sim.snapshot().loadLists[0].lines[0].status,'PARTIALLY ALLOCATED');assert.throws(()=>f.cmd('dispatch',{id:f.truck.id,destination:f.site.id}),/loading task was cancelled/);}f.cmd('cancelLoadList',{id:list.id,reason:'Re-list tomorrow'});assert.equal(f.sim.snapshot().loadLists[0].status,'CANCELLED');assert.equal(f.total(),200);assert.ok(loadedOnTruck>=0);});

test('the delivery docket freezes what left the yard and a repacked remainder stays reserved',t=>{const f=fixture(t);const list=f.cmd('createLoadList',{name:'Docket',site:f.site.id,lines:[{product:f.products[0].id,quantity:120},{product:f.products[1].id,quantity:5}]});f.cmd('allocateLoadList',{id:list.id,truck:f.truck.id});f.tick(3);const repack=f.sim.tasks().find(t=>t.type==='REPACK');f.tick(200);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(200);const empty=f.sim.repo.get(f.empty.id);assert.equal(f.sim.repo.quantity(empty.id,f.products[0].id),20);assert.equal(f.sim.snapshot().reservedTotal,0);f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});const view=f.sim.snapshot().loadLists[0];assert.equal(view.lines[0].sent,120);assert.equal(view.lines[1].sent,0);assert.equal(view.lines[1].status,'REQUESTED');f.cmd('purchase',{container:f.b.id,product:f.products[0].id,quantity:5,reason:'Top up'});assert.equal(f.sim.snapshot().loadLists[0].lines[0].sent,120);assert.ok(repack);assert.equal(f.total(),205);});

test('general managers can record purchases and removals; supervisors still cannot',t=>{const f=fixture(t);f.auth.addUser(f.user,{name:'Manager',email:'manager@example.com',password:'demonstration-password',roles:['GENERAL_MANAGER']});f.auth.addUser(f.user,{name:'Supervisor',email:'supervisor@example.com',password:'demonstration-password',roles:['SUPERVISOR']});const as=email=>new Simulation(f.db,f.auth.authenticate(f.auth.login({email,password:'demonstration-password'})));const manager=as('manager@example.com'),supervisor=as('supervisor@example.com');assert.ok(f.auth.permissions(manager.user).includes('stock.adjust'));assert.ok(!f.auth.permissions(supervisor.user).includes('stock.adjust'));manager.execute('purchase',{container:f.empty.id,product:f.products[0].id,quantity:10,reason:'Manager purchase'},randomUUID());assert.equal(f.total(),210);manager.execute('removeStock',{container:f.empty.id,product:f.products[0].id,quantity:4,reason:'Manager sale'},randomUUID());assert.equal(f.total(),206);assert.throws(()=>supervisor.execute('purchase',{container:f.empty.id,product:f.products[0].id,quantity:1,reason:'Not allowed'},randomUUID()),/role does not allow/);assert.throws(()=>supervisor.execute('removeStock',{container:f.empty.id,product:f.products[0].id,quantity:1,reason:'Not allowed'},randomUUID()),/role does not allow/);assert.equal(f.total(),206);assert.ok(f.sim.snapshot().additions.some(l=>l.reason==='Manager purchase'));});

test('home quick adjustments add and retire idle workers, forklifts, trucks and empty stillages with guards',t=>{const f=fixture(t);const count=(kind)=>{const s=f.sim.snapshot();return kind==='TRUCK'?s.trucks.length:kind==='STILLAGE'?s.containers.filter(c=>c.location===f.yard.id&&c.type==='STILLAGE').length:s.resources.filter(r=>r.type===kind&&r.location===f.yard.id).length;};const q=(kind,delta)=>f.cmd('quickAdjust',{kind,delta,location:f.yard.id});assert.equal(count('WORKER'),5);q('WORKER',1);assert.equal(count('WORKER'),6);assert.equal(f.sim.snapshot().resources.filter(r=>r.type==='WORKER'&&r.location===f.yard.id).at(-1).name,'Worker 6');q('WORKER',-1);assert.equal(count('WORKER'),5);assert.equal(count('FORKLIFT'),1);q('FORKLIFT',1);assert.equal(count('FORKLIFT'),2);const added=f.sim.snapshot().resources.filter(r=>r.type==='FORKLIFT').at(-1);assert.equal(added.capacity,1500000);q('FORKLIFT',-1);assert.equal(count('FORKLIFT'),1);q('TRUCK',1);assert.equal(count('TRUCK'),2);const newTruck=f.sim.snapshot().trucks.at(-1);assert.match(newTruck.name,/^T-[0-9][0-9]$/);assert.notEqual(newTruck.id,f.truck.id);q('TRUCK',-1);assert.equal(count('TRUCK'),1);assert.equal(f.sim.snapshot().trucks[0].id,f.truck.id);const before=count('STILLAGE');q('STILLAGE',1);assert.equal(count('STILLAGE'),before+1);const fresh=f.sim.snapshot().containers.filter(c=>c.location===f.yard.id).at(-1);assert.equal(fresh.name,'S-001');assert.equal(f.sim.repo.lines(fresh.id).length,0);q('STILLAGE',-1);assert.equal(count('STILLAGE'),before);assert.ok(f.sim.repo.get(fresh.id).retired);assert.ok(f.sim.repo.history(300).some(l=>l.event==='CONTAINER_RETIRED'&&l.container_id===fresh.id));q('STILLAGE',-1);assert.equal(count('STILLAGE'),before-1);assert.ok(f.sim.repo.get(f.empty.id).retired);assert.throws(()=>q('STILLAGE',-1),/holds stock|in use/);assert.equal(f.total(),200);f.cmd('queue',{container:f.a.id,destination:f.truck.id});f.tick(3);assert.throws(()=>q('TRUCK',-1),/loaded|away|planned/);const busy=f.sim.snapshot().resources.filter(r=>r.type==='WORKER'&&r.location===f.yard.id);for(const w of busy.filter(r=>!r.task))f.cmd('workerCommand',{id:w.id,order:'MOVE',x:15000,y:12000});assert.throws(()=>q('WORKER',-1),/busy/);assert.throws(()=>q('FORKLIFT',-1),/busy/);assert.throws(()=>q('WORKER',2),/\+1 or -1/);assert.throws(()=>q('CRANE',1),/workers, forklifts, trucks or stillages/);assert.equal(f.total(),200);});

test('retire removes a chosen worker, forklift, truck or empty stillage and refuses busy or loaded ones',t=>{const f=fixture(t);const snap=()=>f.sim.snapshot();const workers=()=>snap().resources.filter(r=>r.type==='WORKER'&&r.location===f.yard.id);const w2=workers()[1];f.cmd('retire',{id:w2.id});assert.ok(!workers().some(r=>r.id===w2.id));assert.equal(workers().length,4);const w1=workers()[0];f.cmd('workerCommand',{id:w1.id,order:'MOVE',x:15000,y:12000});assert.throws(()=>f.cmd('retire',{id:w1.id}),/busy/);f.cmd('workerCommand',{id:w1.id,order:'STOP'});const forklift=snap().resources.find(r=>r.type==='FORKLIFT');f.cmd('workerCommand',{id:w1.id,order:'MOUNT',forklift:forklift.id});assert.throws(()=>f.cmd('retire',{id:forklift.id}),/in use/);assert.throws(()=>f.cmd('retire',{id:w1.id}),/busy/);f.cmd('workerCommand',{id:w1.id,order:'STOP'});f.cmd('retire',{id:forklift.id});assert.ok(!snap().resources.some(r=>r.id===forklift.id));assert.throws(()=>f.cmd('retire',{id:f.a.id}),/holds stock/);f.cmd('retire',{id:f.empty.id});assert.ok(!snap().containers.some(c=>c.id===f.empty.id));assert.ok(f.sim.repo.get(f.empty.id).retired);assert.throws(()=>f.cmd('retire',{id:f.empty.id}),/already removed/);f.cmd('queue',{container:f.a.id,destination:f.truck.id});assert.throws(()=>f.cmd('retire',{id:f.truck.id}),/Unload the truck/);const t2=f.cmd('truck',{name:'T02',yard:f.yard.id});f.cmd('retire',{id:t2.id});assert.ok(!snap().trucks.some(x=>x.id===t2.id));assert.equal(f.sim.repo.get(t2.id).status,'RETIRED');assert.throws(()=>f.cmd('queue',{container:f.b.id,destination:t2.id}),/not available/);assert.throws(()=>f.cmd('retire',{id:f.yard.id}),/worker, forklift, truck or stillage/);assert.equal(f.total(),200);});

test('a truck can be removed while parked at a site but not while travelling or loaded',t=>{const f=fixture(t);f.cmd('queue',{container:f.a.id,destination:f.truck.id});f.tick(150);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(150);f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});assert.equal(f.sim.repo.get(f.truck.id).status,'IN_TRANSIT');assert.throws(()=>f.cmd('retire',{id:f.truck.id}),/travelling/);f.tick(20);assert.equal(f.sim.repo.get(f.truck.id).status,'AT_SITE');assert.throws(()=>f.cmd('retire',{id:f.truck.id}),/Unload the truck/);f.cmd('unload',{id:f.truck.id});f.tick(300);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(300);assert.equal(f.sim.repo.get(f.a.id).location,f.site.id);f.cmd('retire',{id:f.truck.id});assert.equal(f.sim.repo.get(f.truck.id).status,'RETIRED');assert.ok(!f.sim.snapshot().trucks.some(x=>x.id===f.truck.id));assert.throws(()=>f.cmd('returnStock',{container:f.a.id,truck:f.truck.id}),/empty truck|not available|arrive/);assert.equal(f.total(),200);});

test('purgeDemo removes demonstration stock and hides demo products, but refuses while they are reserved',t=>{const f=fixture(t);assert.equal(f.total(),200);f.cmd('queue',{container:f.a.id,destination:f.truck.id});assert.throws(()=>f.cmd('purgeDemo',{}),/active movement|reserved/);f.cmd('cancel',{id:f.sim.tasks()[0].id});const result=f.cmd('purgeDemo',{});assert.equal(result.products,3);assert.equal(result.pieces,200);assert.equal(f.total(),0);const s=f.sim.snapshot();assert.ok(s.products.every(p=>p.retired));assert.equal(s.register.length,0);assert.equal(s.additions.length,0);assert.equal(s.removals.length,0);assert.equal(f.sim.repo.history(300).filter(l=>l.event==='DEMO_PURGED').length,2);assert.throws(()=>f.cmd('purgeDemo',{}),/no demonstration data/);f.cmd('retire',{id:f.a.id});assert.ok(f.sim.repo.get(f.a.id).retired);assert.throws(()=>f.cmd('seed',{}),/already been configured/);});

test('resizing the yard relocates stillages and stacks inside the new boundary, re-seats crew and keeps totals',t=>{const f=fixture(t);const upper=f.container('Upper',7000,4000,{support:f.b.id});const w=f.sim.snapshot().resources.find(r=>r.type==='WORKER'&&r.location===f.yard.id);f.cmd('workerCommand',{id:w.id,order:'MOVE',x:17000,y:12000});f.tick(4);assert.ok(f.sim.repo.get(w.id).walk);const seg=(w,h)=>[{direction:'RIGHT',length:w},{direction:'DOWN',length:h},{direction:'LEFT',length:w}];const result=f.cmd('yard',{id:f.yard.id,name:'Smaller',segments:seg(8000,16000),closed:true,loading:{x:14000,y:12000},gate:{x:1000,y:12000}});assert.match(result.message,/Moved 3 stillage/);assert.match(result.message,/Loading zone moved/);assert.deepEqual(result.relocated.sort(),['B','Empty','Upper']);const yard=f.sim.repo.get(f.yard.id);assert.equal(yard.name,'Smaller');for(const c of f.sim.containers().filter(c=>c.location===yard.id)){assert.ok(fitsPolygon(f.sim.rect?f.sim.rect(c):{x:c.x,y:c.y,w:c.rotation===90?c.envelopeWidth:c.envelopeLength,h:c.rotation===90?c.envelopeLength:c.envelopeWidth},yard.points),c.name+' inside');assert.equal(c.support,null);}assert.equal(f.sim.repo.get(f.a.id).x,4000);assert.equal(f.total(),200);assert.equal(f.sim.repo.history(400).filter(l=>l.event==='RELOCATED').length,3);assert.ok(fitsPolygon({...yard.loading,w:2000,h:1500},yard.points));const walker=f.sim.repo.get(w.id);assert.equal(walker.walk,null);assert.equal(walker.workerMode,'HOLD');f.tick(3);for(const r of f.sim.snapshot().resources.filter(r=>r.location===yard.id))assert.ok(Number.isFinite(r.x)&&r.x>=0&&r.x<8000,r.name+' re-seated');f.cmd('queue',{container:f.a.id,destination:f.truck.id});f.tick(150);assert.equal(f.sim.repo.get(f.a.id).location,f.truck.id);});

test('a yard too small for its stock is refused and rolled back; a mounted forklift and its driver move together',t=>{const f=fixture(t);const before=f.sim.repo.get(f.yard.id);const seg=(w,h)=>[{direction:'RIGHT',length:w},{direction:'DOWN',length:h},{direction:'LEFT',length:w}];assert.throws(()=>f.cmd('yard',{id:f.yard.id,name:'Tiny',segments:seg(3000,3000),closed:true}),/too small|clear|footprint/);assert.throws(()=>f.cmd('yard',{id:f.yard.id,name:'Tiny',segments:seg(4000,2500),closed:true}),/too small|clear|footprint/);const after=f.sim.repo.get(f.yard.id);assert.equal(after.name,before.name);assert.deepEqual(after.points,before.points);assert.equal(f.sim.repo.get(f.b.id).x,7000);assert.equal(f.sim.repo.history(400).filter(l=>l.event==='RELOCATED').length,0);const ws=f.sim.snapshot().resources.filter(r=>r.type==='WORKER'&&r.location===f.yard.id),m=f.sim.snapshot().resources.find(r=>r.type==='FORKLIFT');f.cmd('workerCommand',{id:ws[0].id,order:'MOUNT',forklift:m.id});f.tick(50);assert.equal(f.sim.repo.get(ws[0].id).mountedOn,m.id);const shrunk=f.cmd('yard',{id:f.yard.id,name:'Yard',segments:seg(6000,16000),closed:true});assert.match(shrunk.message,/Saved/);const m2=f.sim.repo.get(m.id),d2=f.sim.repo.get(ws[0].id);assert.equal(d2.mountedOn,m.id);assert.ok(Number.isFinite(m2.x)&&m2.x+2200<=6000,'forklift inside');assert.equal(d2.x,m2.x+600);f.cmd('workerCommand',{id:ws[0].id,order:'DISMOUNT'});const ok=f.cmd('yard',{id:f.yard.id,name:'Yard',segments:seg(20000,16000),closed:true});assert.match(ok.message,/Saved/);assert.equal(f.total(),200);});

test('resize handles diagonal edges, sibling stillages blocking each other, crew under relocated stock and lowered height',t=>{const f=fixture(t);f.tick(2);const seated=f.sim.snapshot().resources.filter(r=>r.location===f.yard.id&&Number.isFinite(r.x));assert.ok(seated.length>=5);const diagonal=[{direction:'RIGHT',length:14000},{direction:'SE',length:2000},{direction:'DOWN',length:10000},{direction:'LEFT',length:15414}];const r1=f.cmd('yard',{id:f.yard.id,name:'Diagonal',segments:diagonal,closed:true});assert.match(r1.message,/Saved/);const yard=f.sim.repo.get(f.yard.id);const inside=c=>fitsPolygon({x:c.x,y:c.y,w:c.rotation===90?c.envelopeWidth:c.envelopeLength,h:c.rotation===90?c.envelopeLength:c.envelopeWidth},yard.points);for(const c of f.sim.containers().filter(c=>c.location===yard.id))assert.ok(inside(c),c.name);const rects=f.sim.containers().filter(c=>c.location===yard.id).map(c=>({x:c.x,y:c.y,w:c.rotation===90?c.envelopeWidth:c.envelopeLength,h:c.rotation===90?c.envelopeLength:c.envelopeWidth}));for(let i=0;i<rects.length;i++)for(let j=i+1;j<rects.length;j++)assert.ok(!(rects[i].x<rects[j].x+rects[j].w&&rects[j].x<rects[i].x+rects[i].w&&rects[i].y<rects[j].y+rects[j].h&&rects[j].y<rects[i].y+rects[i].h),'no overlap');f.tick(3);for(const r of f.sim.snapshot().resources.filter(r=>r.location===yard.id)){assert.ok(Number.isFinite(r.x),r.name+' seated');const foot=r.type==='FORKLIFT'?{x:r.x,y:r.y,w:2200,h:1200}:{x:r.x,y:r.y,w:500,h:500};assert.ok(!rects.some(o=>foot.x<o.x+o.w&&o.x<foot.x+foot.w&&foot.y<o.y+o.h&&o.y<foot.y+foot.h),r.name+' not under a stillage');}const worker=f.sim.snapshot().resources.find(r=>r.type==='WORKER'&&r.location===yard.id);f.cmd('workerCommand',{id:worker.id,order:'MOVE',x:6000,y:6000});assert.ok(f.sim.repo.get(worker.id).walk,'worker can still be moved');const upper=f.container('Up',4000,4000,{support:f.a.id});const r2=f.cmd('yard',{id:f.yard.id,name:'Low',segments:diagonal,closed:true,height:1500});assert.ok(r2.relocated.includes('Up'));assert.equal(f.sim.repo.get(upper.id).support,null);assert.throws(()=>f.cmd('yard',{id:f.yard.id,name:'Lower',segments:diagonal,closed:true,height:900}),/lower than a stored stillage/);assert.equal(f.total(),200);});

test('site boundaries can be drawn and resized with stock and crew on site; in-flight yard movements are re-planned not refused',t=>{const f=fixture(t);const seg=(w,h)=>[{direction:'RIGHT',length:w},{direction:'DOWN',length:h},{direction:'LEFT',length:w}];const queued=f.cmd('queue',{container:f.a.id,destination:f.truck.id});f.tick(2);const mid=f.sim.repo.get(queued.id);assert.ok(['RESERVED','ASSIGNED','TRAVELLING_TO_PICKUP','PICKING','CARRYING'].includes(mid.state),mid.state);const r=f.cmd('yard',{id:f.yard.id,name:'Yard',segments:seg(18000,16000),closed:true});assert.match(r.message,/Saved/);f.tick(200);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(200);assert.equal(f.sim.repo.get(f.a.id).location,f.truck.id);f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(20);f.cmd('unload',{id:f.truck.id});f.tick(300);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(300);assert.equal(f.sim.repo.get(f.a.id).location,f.site.id);const before=f.sim.repo.get(f.site.id);assert.equal(before.segments,undefined);const resized=f.cmd('siteBoundary',{id:f.site.id,segments:seg(8000,6000),closed:true,height:8000});assert.match(resized.message,/Saved/);const site=f.sim.repo.get(f.site.id);assert.equal(site.segments.length,3);assert.equal(site.height,8000);const a=f.sim.repo.get(f.a.id);assert.ok(fitsPolygon({x:a.x,y:a.y,w:a.rotation===90?a.envelopeWidth:a.envelopeLength,h:a.rotation===90?a.envelopeLength:a.envelopeWidth},site.points),'stock inside the new site boundary');assert.ok(fitsPolygon({...site.loading,w:2000,h:1500},site.points));f.tick(3);for(const w of f.sim.snapshot().resources.filter(r=>r.type==='WORKER'&&r.location===site.id))assert.ok(Number.isFinite(w.x)&&w.x<8000,w.name+' seated on site');assert.throws(()=>f.cmd('siteBoundary',{id:f.site.id,segments:seg(2500,2500),closed:true}),/too small|footprint/);assert.equal(f.sim.repo.get(f.site.id).height,8000);assert.equal(f.total(),200);});

test('stock intake fills the first available stillage, tops up, then stacks new stillages like a stockpile',t=>{const f=fixture(t);const ledger=f.products[0];assert.equal(f.sim.effective(ledger.id).packQuantity,100);const r1=f.cmd('stockIntake',{location:f.yard.id,product:ledger.id,quantity:40,kind:'ORIGINAL'});assert.deepEqual(r1.filled.map(x=>[x.name,x.quantity,x.created]),[['Empty',40,false]]);assert.equal(f.sim.repo.quantity(f.empty.id,ledger.id),40);const r2=f.cmd('stockIntake',{location:f.yard.id,product:ledger.id,quantity:80,kind:'PURCHASE',reason:'Invoice 7'});assert.deepEqual(r2.filled.map(x=>[x.name,x.quantity,x.created,x.stackedOn]),[['Empty',60,false,null],['S-001',20,true,'A']]);const s001=f.sim.containers().find(c=>c.name==='S-001');assert.equal(s001.support,f.a.id);assert.equal(s001.x,f.a.x);assert.equal(f.total(),320);assert.match(r2.message,/S-001 \(20, new · stacked on A\)/);const r3=f.cmd('stockIntake',{location:f.yard.id,product:ledger.id,quantity:250,kind:'PURCHASE'});const created=r3.filled.filter(x=>x.created);assert.equal(r3.filled.reduce((n,x)=>n+x.quantity,0),250);assert.ok(created.every(x=>x.quantity<=100));const stored=f.sim.containers().filter(c=>c.location===f.yard.id);const levels=stored.map(c=>{let n=1,cur=c;while(cur.support){n++;cur=stored.find(o=>o.id===cur.support);}return n;});assert.ok(Math.max(...levels)>=2,'stacked');assert.ok(Math.max(...levels)<=7);assert.equal(f.total(),570);assert.equal(f.sim.snapshot().additions.filter(l=>l.reason==='Invoice 7').length,2);const request=f.cmd('request',{site:f.site.id,product:ledger.id,quantity:100});const allocated=f.cmd('allocate',{id:request.id,truck:f.truck.id});assert.ok(allocated.tasks.length,'top-of-stack stock can be loaded');f.tick(300);for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(300);assert.equal(f.sim.snapshot().trucks[0].loadedWeight>0,true);assert.equal(f.total(),570);const unknown=f.products[2];const r4=f.cmd('stockIntake',{location:f.yard.id,product:unknown.id,quantity:5,kind:'ORIGINAL'});assert.equal(r4.filled.length,1);assert.throws(()=>f.cmd('stockIntake',{location:f.yard.id,product:ledger.id,quantity:0,kind:'ORIGINAL'}),/Quantity/);});

test('quick adjust creates and removes 2 tonne and 12.5 tonne trucks as separate classes',t=>{const f=fixture(t);const q=(delta,payload)=>f.cmd('quickAdjust',{kind:'TRUCK',delta,location:f.yard.id,...(payload?{payload}:{})});const light=q(1,2000000);assert.equal(light.payload,2000000);assert.equal(light.length,4200);assert.equal(light.stackLimit,1);assert.match(light.name,/^L-\d\d$/);const heavy=q(1,12500000);assert.equal(heavy.payload,12500000);assert.equal(heavy.length,6000);const trucks=()=>f.sim.snapshot().trucks;assert.equal(trucks().filter(x=>x.payload<10000000).length,1);assert.equal(trucks().filter(x=>x.payload>=10000000).length,2);q(-1,2000000);assert.equal(trucks().filter(x=>x.payload<10000000).length,0);assert.throws(()=>q(-1,2000000),/2 tonne/);assert.throws(()=>q(1,5000000),/2 tonne or 12.5 tonne/);q(-1,12500000);assert.equal(trucks().filter(x=>x.payload>=10000000).length,1);assert.equal(trucks()[0].id,f.truck.id);});
test('yard fixtures: solid ones relocate stock, block placement and routing; truck lanes only keep stock clear',t=>{const f=fixture(t);const r=f.cmd('fixtures',{id:f.yard.id,fixtures:[{kind:'OFFICE',x:3500,y:3500},{kind:'ENTRY',x:12000,y:12000,name:'Truck entry'}]});assert.deepEqual([...r.relocated].sort(),['A','B']);assert.equal(f.sim.repo.get(f.yard.id).fixtures.length,2);assert.equal(f.total(),200);for(const c of [f.a,f.b]){const now=f.sim.repo.get(c.id),w=now.rotation===90?1000:2000,h=now.rotation===90?2000:1000;assert.ok(!(now.x<9500&&now.x+w>3500&&now.y<6500&&now.y+h>3500),c.name+' cleared the office');}assert.throws(()=>f.container('X',4000,4000),/yard office/);assert.throws(()=>f.container('Y',12500,12500),/truck entry/);const obstacles=f.sim.workerObstacles(f.yard.id);assert.ok(obstacles.some(o=>o.x===3500&&o.y===3500&&o.w===6000&&o.h===3000),'office is a routing obstacle');assert.ok(!obstacles.some(o=>o.x===12000&&o.w===4000),'lane is not a routing obstacle');assert.throws(()=>f.cmd('fixtures',{id:f.yard.id,fixtures:[{kind:'OFFICE',x:3500,y:3500},{kind:'TOILET',x:4000,y:4000}]}),/overlaps/);assert.throws(()=>f.cmd('fixtures',{id:f.yard.id,fixtures:[{kind:'OFFICE',x:18000,y:14000}]}),/inside the boundary/);assert.throws(()=>f.cmd('yard',{name:'Second',segments:[{direction:'RIGHT',length:12000},{direction:'DOWN',length:10000},{direction:'LEFT',length:12000}],closed:true,fixtures:[{kind:'TOILET',x:1000,y:1000}]}),/loading zone/);const worker=f.sim.snapshot().resources.find(x=>x.type==='WORKER'&&x.location===f.yard.id);assert.throws(()=>f.cmd('workerCommand',{id:worker.id,order:'MOVE',x:5000,y:4500}),/No clear walking route/);const moved=f.cmd('fixtures',{id:f.yard.id,fixtures:[{kind:'OFFICE',x:14000,y:500},{kind:'ENTRY',x:12000,y:12000}]});assert.equal(moved.relocated.length,0);});
test('stockpile removal takes from the highest, newest reachable stillage and refuses reserved, buried or missing stock',t=>{const f=fixture(t);const ledger=f.products[0];f.cmd('stockIntake',{location:f.yard.id,product:ledger.id,quantity:250,kind:'PURCHASE'});assert.equal(f.total(),450);const r=f.cmd('stockRemoval',{location:f.yard.id,product:ledger.id,quantity:120,reason:'Sold to customer'});assert.deepEqual(r.taken.map(x=>[x.name,x.quantity,x.emptied]),[['S-002',50,true],['S-001',70,false]]);assert.equal(f.total(),330);assert.match(r.message,/120 × /);assert.equal(f.sim.snapshot().removals.filter(l=>l.reason==='Sold to customer').reduce((s,l)=>s+l.quantity,0),120);f.cmd('queue',{container:f.empty.id,destination:f.truck.id});assert.throws(()=>f.cmd('stockRemoval',{location:f.yard.id,product:ledger.id,quantity:200}),/Only 30 × /);assert.throws(()=>f.cmd('stockRemoval',{location:f.yard.id,product:f.products[2].id,quantity:1}),/no .* in the yard/);const again=f.cmd('stockRemoval',{location:f.yard.id,product:ledger.id,quantity:30});assert.deepEqual(again.taken.map(x=>[x.name,x.quantity]),[['S-001',30]]);assert.throws(()=>f.cmd('stockRemoval',{location:f.yard.id,product:ledger.id,quantity:1}),/None of the 300/);assert.equal(f.total(),300);const back=f.cmd('stockIntake',{location:f.yard.id,product:f.products[2].id,quantity:5,kind:'PURCHASE'});assert.equal(back.filled[0].created,false,'an emptied stillage is reused before a new one is stacked');});
test('layout planner sequences a swap through a temporary spot, commits chained instructions and the crew carries them out',t=>{const f=fixture(t);const moves=[{container:f.a.id,x:7000,y:4000,rotation:0},{container:f.b.id,x:4000,y:4000,rotation:0}];const preview=f.sim.layoutPreview({yard:f.yard.id,moves});assert.equal(preview.ok,true,preview.message);assert.equal(preview.steps.length,3);assert.equal(preview.steps.filter(s=>s.park).length,1);assert.equal(preview.steps[0].name,'A');assert.equal(preview.steps[0].park,true);assert.equal(preview.steps[2].name,'A');assert.deepEqual(preview.steps[2].to,{x:7000,y:4000,rotation:0,support:null});assert.equal(f.sim.tasks().length,0,'preview creates nothing');const bad=f.sim.layoutPreview({yard:f.yard.id,moves:[{container:f.a.id,x:-5000,y:4000,rotation:0}]});assert.equal(bad.ok,false);assert.match(bad.message,/outside the yard boundary/);const r=f.cmd('commitLayout',{yard:f.yard.id,moves,name:'Swap A and B'});assert.equal(r.tasks.length,3);assert.equal(r.tasks[1].dependency,r.tasks[0].id);assert.equal(r.tasks[2].dependency,r.tasks[1].id);assert.match(r.message,/3 instructions sent/);assert.throws(()=>f.cmd('commitLayout',{yard:f.yard.id,moves:[{container:f.empty.id,x:12000,y:8000,rotation:0}]}),/Finish or cancel the current layout plan/);assert.throws(()=>f.cmd('queue',{container:f.a.id,destination:f.truck.id}),/active movement/);f.tick(120);assert.deepEqual(f.sim.tasks().filter(x=>x.state==='BLOCKED').map(x=>x.reason),[]);const a=f.sim.repo.get(f.a.id),b=f.sim.repo.get(f.b.id);assert.deepEqual([a.x,a.y,a.support,b.x,b.y,b.support],[7000,4000,null,4000,4000,null]);assert.equal(f.total(),200);const layout=f.sim.layouts()[0];assert.equal(layout.status,'COMPLETE');assert.equal(layout.done,3);assert.equal(f.sim.repo.history(500).filter(l=>l.event==='PLACEMENT').length,3);assert.equal(f.sim.repo.history(500).filter(l=>l.event==='LAYOUT_PLANNED').length,1);});
test('layout planner moves a whole pile by setting the top down first, refuses a buried move, and cancels remaining steps in order',t=>{const f=fixture(t);f.cmd('queue',{container:f.empty.id,destination:f.yard.id,position:{x:4000,y:4000,rotation:0,support:f.a.id}});f.tick(60);assert.equal(f.sim.repo.get(f.empty.id).support,f.a.id);assert.throws(()=>f.cmd('commitLayout',{yard:f.yard.id,moves:[{container:f.a.id,x:12000,y:8000,rotation:0}]}),/Empty is stacked on A/);assert.throws(()=>f.cmd('commitLayout',{yard:f.yard.id,moves:[{container:f.empty.id,x:7000,y:4000,rotation:0,support:f.b.id},{container:f.b.id,x:4000,y:4000,rotation:0,support:f.empty.id}]}),/loop|overlap|fully on/);const moves=[{container:f.a.id,x:12000,y:8000,rotation:90},{container:f.empty.id,x:12000,y:8000,rotation:90,support:f.a.id}];const preview=f.sim.layoutPreview({yard:f.yard.id,moves});assert.equal(preview.ok,true,preview.message);assert.deepEqual(preview.steps.map(s=>[s.name,s.park]),[['Empty',true],['A',false],['Empty',false]]);assert.equal(preview.steps[2].to.support,f.a.id);const r=f.cmd('commitLayout',{yard:f.yard.id,moves});f.tick(1);const cancelled=f.cmd('cancelLayout',{id:r.layout.id});assert.equal(cancelled.cancelled+cancelled.kept,3);assert.ok(f.sim.layouts().every(l=>l.status==='CANCELLED'));f.tick(60);assert.deepEqual(f.sim.tasks().filter(x=>x.state==='BLOCKED'),[]);const r2=f.cmd('commitLayout',{yard:f.yard.id,moves:[{container:f.a.id,x:12000,y:8000,rotation:90},{container:f.empty.id,x:12000,y:8000,rotation:90,support:f.a.id}]});assert.equal(r2.tasks.length,3);f.tick(200);for(const task of f.sim.tasks().filter(x=>x.state==='BLOCKED'))f.cmd('retry',{id:task.id});f.tick(200);assert.deepEqual(f.sim.tasks().filter(x=>x.state==='BLOCKED').map(x=>x.reason),[]);const a=f.sim.repo.get(f.a.id),top=f.sim.repo.get(f.empty.id);assert.deepEqual([a.x,a.y,a.rotation,a.support],[12000,8000,90,null]);assert.deepEqual([top.x,top.y,top.rotation,top.support],[12000,8000,90,f.a.id]);assert.equal(f.total(),200);assert.equal(f.sim.layouts().at(-1).status,'COMPLETE');});

test('a yard crewed only through the +1 buttons gets an engine config and its tasks run',t=>{const db=openDatabase(':memory:');t.after(()=>db.close());const auth=new Service(db);const user=auth.authenticate(auth.register({name:'Owner',companyName:'Quick',email:randomUUID()+'@example.com',password:'demonstration-password',systems:['quickstage']}));const sim=new Simulation(db,user);const cmd=(action,input={})=>sim.execute(action,input,randomUUID());const yard=cmd('yard',{name:'Yard',segments:[{direction:'RIGHT',length:20000},{direction:'DOWN',length:16000},{direction:'LEFT',length:20000}],closed:true});assert.equal(sim.repo.all('config').length,0);cmd('quickAdjust',{kind:'WORKER',delta:1,location:yard.id});cmd('quickAdjust',{kind:'FORKLIFT',delta:1,location:yard.id});assert.equal(sim.repo.all('config').length,1);const c=cmd('container',{name:'A',location:yard.id,type:'STILLAGE',length:2000,width:1000,height:1000,tare:50000,x:4000,y:4000});const task=cmd('queue',{container:c.id,destination:yard.id,position:{x:9000,y:4000,rotation:0,support:null}});for(let i=0;i<40;i++)atomic(db,()=>sim.tick(1000));assert.equal(sim.repo.get(task.id).state,'COMPLETE');assert.deepEqual([sim.repo.get(c.id).x,sim.repo.get(c.id).y],[9000,4000]);});
test('the top of a three-high pile can be moved by the engine and the planner, and stacked onto a two-high pile',t=>{const f=fixture(t);const b2=f.container('B2',4000,4000,{support:f.a.id}),c3=f.container('C3',4000,4000,{support:b2.id});const d2=f.container('D2',7000,4000,{support:f.b.id});const preview=f.sim.layoutPreview({yard:f.yard.id,moves:[{container:c3.id,x:7000,y:4000,rotation:0,support:d2.id}]});assert.equal(preview.ok,true,preview.message);assert.deepEqual(preview.steps.map(s=>[s.name,s.park]),[['C3',false]]);const task=f.cmd('queue',{container:c3.id,destination:f.yard.id,position:{x:7000,y:4000,rotation:0,support:d2.id}});f.tick(60);assert.equal(f.sim.repo.get(task.id).state,'COMPLETE',f.sim.repo.get(task.id).reason);assert.equal(f.sim.repo.get(c3.id).support,d2.id);assert.equal(f.total(),200);});
test('a planned destination is reserved from the moment the step is queued',t=>{const f=fixture(t);const moves=[{container:f.a.id,x:7000,y:4000,rotation:0},{container:f.b.id,x:4000,y:4000,rotation:0}];const r=f.cmd('commitLayout',{yard:f.yard.id,moves,name:'Swap'});const park=r.layout.steps[0].to;assert.equal(r.layout.steps[0].park,true);assert.throws(()=>f.container('X',park.x,park.y),/overlaps another container or reservation/);assert.throws(()=>f.cmd('queue',{container:f.empty.id,destination:f.yard.id,position:{x:park.x,y:park.y,rotation:0,support:null}}),/overlaps/);const other=f.sim.layoutPreview({yard:f.yard.id,moves:[{container:f.empty.id,x:park.x,y:park.y,rotation:0}]});assert.equal(other.ok,false);assert.match(other.message,/overlap|planned/);f.tick(120);assert.deepEqual(f.sim.tasks().filter(x=>x.state==='BLOCKED').map(x=>x.reason),[]);assert.equal(f.sim.layouts()[0].status,'COMPLETE');const x=f.container('X',park.x,park.y);assert.ok(x.id,'the spot is free again once the plan is done');});
test('site client details are optional, validated, editable by operations only and survive a boundary edit',t=>{const f=fixture(t);assert.equal(f.sim.repo.get(f.site.id).client,null);const b=f.cmd('site',{name:'Site B',address:'1 High St',client:'Acme Builders',contact:'Jane Smith',email:'Jane@Acme.example',phone:'0400 000 000'});assert.equal(b.client,'Acme Builders');assert.equal(b.contact,'Jane Smith');assert.equal(b.email,'jane@acme.example');assert.equal(b.phone,'0400 000 000');assert.throws(()=>f.cmd('site',{name:'Site C',email:'not-an-email'}),/valid contact email/);assert.throws(()=>f.cmd('site',{name:'Site C',client:{}}),/must be text/);assert.throws(()=>f.cmd('site',{name:'Site C',client:'x'.repeat(251)}),/at most 250/);assert.throws(()=>f.cmd('site',{name:'Site C',phone:'1'.repeat(61)}),/at most 60/);const edited=f.cmd('siteDetails',{id:b.id,client:'Acme Ltd'});assert.equal(edited.client,'Acme Ltd');assert.equal(edited.email,'jane@acme.example');assert.equal(edited.phone,'0400 000 000');assert.equal(edited.supervisor,null);assert.throws(()=>f.cmd('siteDetails',{id:b.id,email:'nope'}),/valid contact email/);assert.equal(f.cmd('siteDetails',{id:b.id,phone:''}).phone,null);f.auth.addUser(f.user,{name:'Supervisor',email:'supervisor@example.com',password:'demonstration-password',roles:['SUPERVISOR']});const sup=f.auth.authenticate(f.auth.login({email:'supervisor@example.com',password:'demonstration-password'}));f.cmd('siteDetails',{id:b.id,supervisor:sup.id});assert.equal(f.sim.repo.get(b.id).supervisor,sup.id);assert.equal(f.sim.snapshot().sites.find(s=>s.id===b.id).supervisorName,'Supervisor');assert.equal(f.sim.snapshot().sites.find(s=>s.id===f.site.id).supervisorName,null);assert.ok(f.sim.snapshot().notifications.some(n=>n.title==='Site reassigned'));const restricted=new Simulation(f.db,sup);assert.equal(restricted.snapshot().sites.length,1);assert.throws(()=>restricted.execute('siteDetails',{id:b.id,client:'Hacked'},randomUUID()),{status:403});f.cmd('siteDetails',{id:b.id,name:'Site B renamed'});assert.equal(f.sim.repo.get(b.id).supervisor,sup.id,'omitting supervisor keeps it');assert.equal(f.sim.repo.get(b.id).client,'Acme Ltd','omitting client keeps it');f.cmd('siteBoundary',{id:b.id,segments:[{direction:'RIGHT',length:8000},{direction:'DOWN',length:6000},{direction:'LEFT',length:8000}],closed:true});const after=f.sim.repo.get(b.id);assert.equal(after.client,'Acme Ltd');assert.equal(after.name,'Site B renamed');assert.equal(after.segments.length,3);assert.ok(f.sim.repo.history(300).some(l=>l.event==='SITE_DETAILS'));f.cmd('archive',{id:b.id});assert.throws(()=>f.cmd('siteDetails',{id:b.id,client:'X'}),/active site/);});
test('snapshot groups stock per location and reports each truck loading, unloading, trip, stage and runs done today',t=>{const f=fixture(t);const retry=()=>{for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});},settle=(n=150)=>{f.tick(n);retry();f.tick(n);},snap=()=>f.sim.snapshot(),stg=s=>truckStage(s.trucks[0],s);let s=snap();assert.equal(s.stock[f.yard.id].pieces,200);assert.equal(s.stock[f.yard.id].reserved,0);assert.equal(s.stock[f.yard.id].containers,3,'empties count as stillages at the location');assert.equal(s.stock[f.yard.id].rows.length,1);assert.equal(s.stock[f.yard.id].rows[0].quantity,200);assert.equal(s.stock[f.yard.id].rows[0].containers,2);assert.equal(s.stock[f.yard.id].rows[0].free,200);assert.equal(s.stock[f.yard.id].rows[0].name,f.products[0].name);assert.equal(s.stock[f.site.id],undefined);assert.deepEqual([s.trucks[0].tasksTo,s.trucks[0].tasksStarted,s.trucks[0].tasksFrom,s.trucks[0].trip],[0,0,0,null]);assert.deepEqual(s.runsToday,{heavy:0,light:0});assert.equal(stg(s),'COMPLETE');const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:120});f.cmd('allocate',{id:request.id,truck:f.truck.id});s=snap();assert.equal(s.trucks[0].tasksTo,2,'two MOVE tasks onto the truck; the REPACK goes to the yard');assert.equal(s.trucks[0].tasksStarted,0);assert.equal(s.stock[f.yard.id].reserved,120);assert.equal(s.stock[f.yard.id].rows[0].free,80);assert.equal(stg(s),'SCHEDULED');f.auth.addUser(f.user,{name:'Supervisor',email:'supervisor@example.com',password:'demonstration-password',roles:['SUPERVISOR']});const sup=f.auth.authenticate(f.auth.login({email:'supervisor@example.com',password:'demonstration-password'}));f.cmd('siteDetails',{id:f.site.id,supervisor:sup.id});const theirs=new Simulation(f.db,sup).snapshot();assert.equal(theirs.trucks.length,1,'a truck booked for their site is in scope');assert.equal(theirs.tasks.length,0,'yard loading tasks are not');assert.equal(theirs.trucks[0].tasksTo,2,'but the loading count is');assert.equal(theirs.trucks[0].trip,null);assert.equal(theirs.stock[f.yard.id],undefined);assert.equal(theirs.yards.length,0);f.tick(3);s=snap();assert.ok(s.trucks[0].tasksStarted>=1,'a forklift has taken the first loading task');assert.equal(stg(s),'LOADING');settle(200);s=snap();assert.equal(s.trucks[0].tasksTo,0);assert.equal(s.stock[f.yard.id].pieces,80);assert.equal(s.stock[f.truck.id].pieces,120);assert.equal(s.stock[f.truck.id].containers,2);assert.equal(stg(s),'LOADING');f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});s=snap();assert.equal(s.trucks[0].trip.status,'IN_TRANSIT');assert.equal(s.trucks[0].trip.to,f.site.id);assert.equal(s.trucks[0].trip.completedAt,null);assert.equal(stg(s),'UNLOADING');f.tick(5);s=snap();assert.equal(s.trucks[0].trip.status,'ARRIVED');assert.equal(s.trucks[0].tasksFrom,0);assert.equal(s.stock[f.site.id],undefined,'cargo stays truck stock until unloaded');assert.equal(stg(s),'UNLOADING');f.cmd('unload',{id:f.truck.id});assert.equal(snap().trucks[0].tasksFrom,2);settle(300);s=snap();assert.equal(s.trucks[0].trip.status,'DELIVERED');assert.ok(s.trucks[0].trip.completedAt);assert.equal(s.trucks[0].tasksFrom,0);assert.equal(s.stock[f.site.id].pieces,120);assert.equal(s.stock[f.site.id].containers,2);assert.equal(s.stock[f.truck.id],undefined);assert.deepEqual(s.runsToday,{heavy:1,light:0});assert.equal(f.sim.repo.get(f.truck.id).destination,null);assert.equal(stg(s),'COMPLETE');f.cmd('returnStock',{container:f.a.id,truck:f.truck.id});assert.equal(stg(snap()),'SCHEDULED');settle();assert.equal(stg(snap()),'LOADING');f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});assert.equal(stg(snap()),'UNLOADING');f.tick(5);assert.equal(stg(snap()),'UNLOADING');f.cmd('unload',{id:f.truck.id});settle();s=snap();assert.equal(stg(s),'COMPLETE');assert.equal(s.trucks[0].trip.status,'DELIVERED');assert.deepEqual(s.runsToday,{heavy:2,light:0},'the loaded return leg is a run');assert.equal(f.total(),200);});
test('a request left short by a cancelled loading task closes when its remainder reaches the site, freeing the truck',t=>{const f=fixture(t);const retry=()=>{for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});},settle=(n=150)=>{f.tick(n);retry();f.tick(n);},snap=()=>f.sim.snapshot(),stg=s=>truckStage(s.trucks[0],s);const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:120});const {tasks}=f.cmd('allocate',{id:request.id,truck:f.truck.id});const move=tasks.find(t=>t.type==='MOVE'&&t.dependency),repack=tasks.find(t=>t.type==='REPACK');f.cmd('cancel',{id:move.id});f.cmd('cancel',{id:repack.id});assert.equal(f.sim.repo.get(request.id).status,'PARTIALLY ALLOCATED');assert.equal(stg(snap()),'SCHEDULED');settle();assert.equal(stg(snap()),'LOADING');f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(5);f.cmd('unload',{id:f.truck.id});settle();const r=f.sim.repo.get(request.id);assert.equal(r.status,'DELIVERED');assert.equal(r.delivered,100);assert.equal(r.quantity,120,'the shortfall stays visible');assert.equal(stg(snap()),'COMPLETE');f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});assert.equal(f.total(),200);});
test('cancelling the last open request or yard list clears the truck booking; a loaded truck keeps its site until it is unloaded',t=>{const f=fixture(t);const retry=()=>{for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});},settle=(n=150)=>{f.tick(n);retry();f.tick(n);};const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:100});f.cmd('allocate',{id:request.id,truck:f.truck.id});assert.equal(f.sim.repo.get(f.truck.id).destination,f.site.id);f.cmd('cancelRequest',{id:request.id,reason:'Not needed'});assert.equal(f.sim.repo.get(f.truck.id).destination,null);assert.equal(f.sim.snapshot().trucks[0].tasksTo,0);const list=f.cmd('createLoadList',{name:'List',site:f.site.id,lines:[{product:f.products[0].id,quantity:100}]});f.cmd('allocateLoadList',{id:list.id,truck:f.truck.id});assert.equal(f.sim.repo.get(f.truck.id).destination,f.site.id);f.cmd('cancelLoadList',{id:list.id,reason:'Not needed'});assert.equal(f.sim.repo.get(f.truck.id).destination,null);assert.equal(f.sim.snapshot().loadLists[0].status,'CANCELLED');const again=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:100});f.cmd('allocate',{id:again.id,truck:f.truck.id});settle();assert.equal(f.sim.snapshot().stock[f.truck.id].pieces,100);f.cmd('cancelRequest',{id:again.id,reason:'Changed plan'});assert.equal(f.sim.repo.get(f.truck.id).destination,f.site.id,'a loaded truck keeps its site');let s=f.sim.snapshot();assert.equal(truckStage(s.trucks[0],s),'LOADING');f.cmd('unload',{id:f.truck.id});settle();assert.equal(f.sim.repo.get(f.truck.id).destination,null,'unloading at the yard releases the site');s=f.sim.snapshot();assert.equal(truckStage(s.trucks[0],s),'COMPLETE');assert.equal(f.total(),200);});
test('containers placed at the site count as delivered even if a stillage stays on the truck; dispatch finalises the docket',t=>{const f=fixture(t);const retry=()=>{for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});},settle=(n=150)=>{f.tick(n);retry();f.tick(n);};const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:100});f.cmd('allocate',{id:request.id,truck:f.truck.id});f.cmd('queue',{container:f.empty.id,destination:f.truck.id});settle();f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(5);const d=f.sim.repo.get(f.truck.id).delivery;f.cmd('queue',{container:f.a.id,destination:f.site.id});settle();assert.equal(f.sim.repo.get(request.id).status,'DELIVERED');assert.equal(f.sim.repo.get(d).status,'ARRIVED','the empty stillage is still on the deck');let s=f.sim.snapshot();assert.equal(truckStage(s.trucks[0],s),'UNLOADING');f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});const after=f.sim.repo.get(d);assert.equal(after.status,'DELIVERED');assert.ok(after.completedAt);assert.deepEqual(after.containers,[f.a.id],'the stillage that went home is dropped from the docket');assert.equal(f.sim.snapshot().runsToday.heavy,1);f.tick(5);f.cmd('unload',{id:f.truck.id});settle();assert.equal(f.total(),200);});
test('a return loaded before the last placement does not keep the delivery open',t=>{const f=fixture(t);const retry=()=>{for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});},settle=(n=150)=>{f.tick(n);retry();f.tick(n);};const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:100});f.cmd('allocate',{id:request.id,truck:f.truck.id});f.cmd('queue',{container:f.empty.id,destination:f.truck.id});settle();f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(5);const d=f.sim.repo.get(f.truck.id).delivery;f.cmd('queue',{container:f.a.id,destination:f.site.id});settle();f.cmd('returnStock',{container:f.a.id,truck:f.truck.id});settle();f.cmd('queue',{container:f.empty.id,destination:f.site.id});settle();assert.equal(f.sim.repo.get(f.a.id).location,f.truck.id);assert.equal(f.sim.repo.get(d).status,'DELIVERED');const s=f.sim.snapshot();assert.equal(truckStage(s.trucks[0],s),'LOADING','loaded with returns, ready to go');assert.equal(s.runsToday.heavy,1);assert.equal(f.total(),200);});
test('a load brought straight back is RETURNED, not a run',t=>{const f=fixture(t);const retry=()=>{for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});},settle=(n=150)=>{f.tick(n);retry();f.tick(n);};const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:100});f.cmd('allocate',{id:request.id,truck:f.truck.id});settle();f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(5);const d=f.sim.repo.get(f.truck.id).delivery;f.cmd('cancelRequest',{id:request.id,reason:'No room on site'});f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});assert.equal(f.sim.repo.get(d).status,'RETURNED');assert.equal(f.sim.snapshot().runsToday.heavy,0);f.tick(5);assert.equal(f.total(),200);});
test('runs done today counts loaded legs to or from a site: a collection run counts, empty legs do not',t=>{const f=fixture(t);const retry=()=>{for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});},settle=(n=150)=>{f.tick(n);retry();f.tick(n);};f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});let s=f.sim.snapshot();assert.equal(truckStage(s.trucks[0],s),'SCHEDULED','empty to a site = sent to collect');f.tick(5);s=f.sim.snapshot();assert.equal(truckStage(s.trucks[0],s),'COMPLETE','free at the site until returns are queued');assert.equal(s.runsToday.heavy,0,'an empty leg is not a run');f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});f.tick(5);const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:100});f.cmd('allocate',{id:request.id,truck:f.truck.id});settle();f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(5);f.cmd('unload',{id:f.truck.id});settle();assert.equal(f.sim.snapshot().runsToday.heavy,1);f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});f.tick(5);assert.equal(f.sim.snapshot().runsToday.heavy,1,'driving home empty is not a run');f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(5);f.cmd('returnStock',{container:f.a.id,truck:f.truck.id});settle();f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});f.tick(5);f.cmd('unload',{id:f.truck.id});settle();s=f.sim.snapshot();assert.equal(s.runsToday.heavy,2,'the loaded return leg counts');assert.equal(f.total(),200);});
test('a small order being repacked reads as loading, not scheduled',t=>{const f=fixture(t);const retry=()=>{for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});},settle=(n=150)=>{f.tick(n);retry();f.tick(n);};const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:20});f.cmd('allocate',{id:request.id,truck:f.truck.id});let s=f.sim.snapshot();assert.equal(s.trucks[0].tasksTo,1);assert.equal(s.trucks[0].tasksStarted,0);assert.equal(truckStage(s.trucks[0],s),'SCHEDULED');for(let i=0;i<10&&!f.sim.tasks().some(t=>t.type==='REPACK'&&t.machine);i++)f.tick(1);s=f.sim.snapshot();assert.equal(s.trucks[0].tasksStarted,1,'the REPACK dependency has a forklift');assert.equal(truckStage(s.trucks[0],s),'LOADING');settle();s=f.sim.snapshot();assert.equal(s.stock[f.truck.id].pieces,20);assert.equal(truckStage(s.trucks[0],s),'LOADING');});
test('per-location stock excludes damaged and quarantined stock from free to load',t=>{const f=fixture(t);f.cmd('condition',{id:f.b.id,condition:'DAMAGED',reason:'Inspection'});const s=f.sim.snapshot();const row=s.stock[f.yard.id].rows[0];assert.equal(row.quantity,200);assert.equal(row.unserviceable,100);assert.equal(row.free,100);assert.equal(s.stock[f.yard.id].unserviceable,100);});

test('cancelling every loading task of a quick request reopens it and frees the truck; cancelling a leftover repack after a short delivery keeps it delivered',t=>{const f=fixture(t);const retry=()=>{for(const task of f.sim.tasks().filter(t=>t.state==='BLOCKED'))f.cmd('retry',{id:task.id});},settle=(n=150)=>{f.tick(n);retry();f.tick(n);};const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:100});const {tasks}=f.cmd('allocate',{id:request.id,truck:f.truck.id});f.cmd('cancel',{id:tasks[0].id});const r=f.sim.repo.get(request.id);assert.equal(r.status,'REQUESTED');assert.equal(r.allocated,0);assert.equal(r.truck,null);assert.equal(f.sim.repo.get(f.truck.id).destination,null);let s=f.sim.snapshot();assert.equal(truckStage(s.trucks[0],s),'COMPLETE');assert.equal(s.reservedTotal,0);f.cmd('allocate',{id:request.id,truck:f.truck.id});assert.equal(f.sim.repo.get(request.id).status,'ALLOCATED');f.cmd('cancelRequest',{id:request.id,reason:'Not needed'});assert.throws(()=>f.cmd('site',{name:'Bad',supervisor:{}}),/valid supervisor/);assert.throws(()=>f.cmd('siteDetails',{id:f.site.id,supervisor:['x']}),/valid supervisor/);const small={length:1000,width:1000,envelopeLength:1000,envelopeWidth:1000};f.container('WL',6000,4000,small);f.container('WR',9000,4000,small);f.container('WT',7000,3000);f.container('WB',7000,5000);const short=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:120});const plan=f.cmd('allocate',{id:short.id,truck:f.truck.id});const dependent=plan.tasks.find(x=>x.type==='MOVE'&&x.dependency),repack=plan.tasks.find(x=>x.type==='REPACK'),full=plan.tasks.find(x=>x.type==='MOVE'&&!x.dependency);f.cmd('cancel',{id:dependent.id});assert.equal(f.sim.repo.get(short.id).status,'PARTIALLY ALLOCATED');for(let i=0;i<200&&!(f.sim.repo.get(full.id).state==='COMPLETE'&&f.sim.repo.get(repack.id).state==='BLOCKED');i++)f.tick(1);assert.equal(f.sim.repo.get(full.id).state,'COMPLETE');assert.equal(f.sim.repo.get(repack.id).state,'BLOCKED','the walled-in repack has no forklift lane');assert.equal(f.sim.repo.get(repack.id).picked,false);f.cmd('dispatch',{id:f.truck.id,destination:f.site.id});f.tick(5);f.cmd('unload',{id:f.truck.id});settle();assert.equal(f.sim.repo.get(short.id).status,'DELIVERED');assert.equal(f.sim.repo.get(short.id).delivered,100);f.cmd('cancel',{id:repack.id});assert.equal(f.sim.repo.get(short.id).status,'DELIVERED','cancelling the leftover repack does not reopen a delivered request');assert.equal(f.sim.repo.get(f.truck.id).destination,null);f.cmd('dispatch',{id:f.truck.id,destination:f.yard.id});assert.equal(f.total(),200);assert.ok(f.sim.snapshot().sites[0].lastDeliveryAt,'the site carries its last delivery time');});
test('cancelling a pending manual load after its booking was cancelled releases the truck destination',t=>{const f=fixture(t);const request=f.cmd('request',{site:f.site.id,product:f.products[0].id,quantity:100});f.cmd('allocate',{id:request.id,truck:f.truck.id});const manual=f.cmd('queue',{container:f.empty.id,destination:f.truck.id});f.cmd('cancelRequest',{id:request.id,reason:'Changed'});assert.equal(f.sim.repo.get(f.truck.id).destination,f.site.id,'a pending load keeps the booking');f.cmd('cancel',{id:manual.id});assert.equal(f.sim.repo.get(f.truck.id).destination,null);const s=f.sim.snapshot();assert.equal(truckStage(s.trucks[0],s),'COMPLETE');assert.equal(f.sim.tasks().filter(x=>['QUEUED','RESERVED','ASSIGNED'].includes(x.state)).length,0);});
